bookDetail.requestInfo:
@js:
var host = String(config.host || '') || 'https://www.ijjxsxzw.com';
var u = '';
if (typeof result === 'string' && result) u = result;
if (!u && result && result.url) u = result.url;
if (!u && result && result.detailUrl) u = result.detailUrl;
if (!u && params && params.queryInfo) u = params.queryInfo.url || params.queryInfo.detailUrl || '';
if (!u && params && params.responseUrl) u = params.responseUrl;
u = String(u || '').trim().split(/\s+/)[0] || '';
if (u && u.indexOf('http') !== 0) {
  if (u.indexOf('//') === 0) u = 'https:' + u;
  else if (u.indexOf('/') === 0) u = host + u;
  else u = host + '/' + u;
}
return {'url': u, 'httpHeaders': config.httpHeaders};

